insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-126","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A gas burette delivers 2.24 L of hydrogen, measured at STP. The amount of $\\mathrm{H_2}$ collected is","options":["0.010 mol","0.10 mol","1.0 mol","2.0 mol"],"answer_index":1,"explanation":"Moles $= 2.24 / 22.4 = 0.10$ mol at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-127","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A sealed ampoule contains $3.011 \\times 10^{23}$ molecules of dinitrogen. The mass of that $\\mathrm{N_2}$ sample is","options":["7 g","14 g","28 g","56 g"],"answer_index":1,"explanation":"The count is 0.50 mol; mass $= 0.50 \\times 28 = 14$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-128","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Eight grams of dioxygen and seven grams of dinitrogen are compared atom by atom. The two samples contain","options":["equal numbers of molecules and equal numbers of atoms","equal numbers of molecules but different numbers of atoms","different numbers of molecules but equal numbers of atoms","neither equal molecules nor equal atoms"],"answer_index":0,"explanation":"Both are 0.25 mol of diatomic molecules, so both have $0.25\\,N_A$ molecules and $0.50\\,N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-129","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 0.25 mol sample of $\\mathrm{Ca_3(PO_4)_2}$ is examined. The number of oxygen atoms in the sample is","options":["$0.25\\,N_A$","$1.00\\,N_A$","$2.00\\,N_A$","$8.00\\,N_A$"],"answer_index":2,"explanation":"Each formula unit has 8 oxygen atoms, so $0.25 \\times 8 = 2.00$ mol of O atoms, i.e. $2.00\\,N_A$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-130","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Among 8 g $\\mathrm{O_2}$, 7 g $\\mathrm{N_2}$, 4 g $\\mathrm{He}$ and 9 g $\\mathrm{H_2O}$, the largest number of atoms is present in","options":["8 g $\\mathrm{O_2}$","7 g $\\mathrm{N_2}$","4 g $\\mathrm{He}$","9 g $\\mathrm{H_2O}$"],"answer_index":3,"explanation":"Atom amounts are 0.50, 0.50, 1.0 and 1.5 mol respectively; 9 g water therefore has the most atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-131","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Using H = 1, S = 32 and O = 16, the molar mass of sulphuric acid $\\mathrm{H_2SO_4}$ is","options":["82 g mol$^{-1}$","98 g mol$^{-1}$","114 g mol$^{-1}$","64 g mol$^{-1}$"],"answer_index":1,"explanation":"$2(1) + 32 + 4(16) = 98$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-132","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Calcium carbonate $\\mathrm{CaCO_3}$ (Ca = 40, C = 12, O = 16) has a formula mass of","options":["50 u","84 u","100 u","116 u"],"answer_index":2,"explanation":"$40 + 12 + 48 = 100$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-133","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The percentage by mass of oxygen in water is closest to","options":["11.1%","50%","88.9%","94.1%"],"answer_index":2,"explanation":"Oxygen contributes 16 of the 18 g in one mole of $\\mathrm{H_2O}$, i.e. $16/18 \\times 100 = 88.9\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-134","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In methane, the mass percent of carbon (C = 12, H = 1) works out to","options":["25%","50%","75%","80%"],"answer_index":2,"explanation":"Carbon is 12 g in 16 g of $\\mathrm{CH_4}$, so $12/16 \\times 100 = 75\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-135","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon dioxide is assigned a molecular mass of 44 u because that value equals","options":["12 + 16","12 + 2(16)","2(12) + 16","12 + 32 + 16"],"answer_index":1,"explanation":"One C and two O atoms give $12 + 32 = 44$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-136","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Ammonia’s gram-molecular mass, with N = 14 and H = 1, is","options":["15 g","16 g","17 g","18 g"],"answer_index":2,"explanation":"$14 + 3(1) = 17$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-137","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen’s share of the mass of water, expressed as a percentage, is","options":["5.6%","11.1%","16.0%","18.0%"],"answer_index":1,"explanation":"Two grams of H in 18 g of water give $2/18 \\times 100 = 11.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-138","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Solid sodium hydroxide (Na = 23, O = 16, H = 1) has a molar mass of","options":["23 g mol$^{-1}$","39 g mol$^{-1}$","40 g mol$^{-1}$","58 g mol$^{-1}$"],"answer_index":2,"explanation":"$23 + 16 + 1 = 40$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-139","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The calcium content of pure $\\mathrm{CaCO_3}$ (M = 100 g mol$^{-1}$) by mass percent is","options":["12%","40%","48%","60%"],"answer_index":1,"explanation":"40 g of Ca in 100 g of carbonate is a 40% calcium assay.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-140","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Urea, $\\mathrm{NH_2CONH_2}$ (M = 60 g mol$^{-1}$), is valued as a fertiliser for nitrogen. The nitrogen mass percent in urea is","options":["23.3%","46.7%","53.3%","60.0%"],"answer_index":1,"explanation":"Two N atoms contribute 28 g in 60 g, so $28/60 \\times 100 = 46.7\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-141","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Potassium chlorate $\\mathrm{KClO_3}$ (M = 122.5 g mol$^{-1}$) releases oxygen on heating. Oxygen’s mass percent in $\\mathrm{KClO_3}$ is nearest to","options":["13.1%","26.1%","39.2%","52.2%"],"answer_index":2,"explanation":"Three oxygen atoms weigh 48 g in 122.5 g, giving $48/122.5 \\times 100 \\approx 39.2\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-142","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"From a 50 g laboratory sample of pure $\\mathrm{CaCO_3}$, the mass of oxygen that can be accounted for in the formula is","options":["16 g","24 g","32 g","48 g"],"answer_index":1,"explanation":"Oxygen is 48% of $\\mathrm{CaCO_3}$, so $0.48 \\times 50 = 24$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-143","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Blue vitriol $\\mathrm{CuSO_4 \\cdot 5H_2O}$ (M = 249.5 g mol$^{-1}$) loses its water of crystallisation on strong heating. The mass percent of water in the pentahydrate is nearest to","options":["18.0%","25.0%","36.1%","45.2%"],"answer_index":2,"explanation":"Five water molecules weigh 90 g in 249.5 g, so $90/249.5 \\times 100 \\approx 36.1\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-144","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Haematite $\\mathrm{Fe_2O_3}$ (M = 160 g mol$^{-1}$) is 70% iron by mass. An 80 g ore sample that is 80% pure $\\mathrm{Fe_2O_3}$ (rest gangue) contains iron weighing","options":["44.8 g","56.0 g","64.0 g","70.0 g"],"answer_index":0,"explanation":"Pure oxide in the ore is $0.80 \\times 80 = 64$ g; iron in that oxide is $0.70 \\times 64 = 44.8$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-145","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The empirical formula of a compound is the formula that shows","options":["the actual number of atoms in one molecule","the simplest whole-number ratio of the atoms present","only the metals in the compound","the percentage by mass of each element"],"answer_index":1,"explanation":"Empirical formulae give the smallest integer atom ratio, not necessarily the molecular formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-146","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A molecular formula is related to the empirical formula by a positive integer $n$ such that","options":["molecular formula $= n \\times$ empirical formula","empirical formula $= n \\times$ molecular formula","$n$ equals the number of elements","$n$ is always 1 for covalent compounds"],"answer_index":0,"explanation":"$n = M / $ (empirical formula mass), and the molecular formula is that multiple of the empirical set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-147","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Benzene has molecular formula $\\mathrm{C_6H_6}$. Its empirical formula is therefore","options":["$\\mathrm{CH}$","$\\mathrm{C_2H_2}$","$\\mathrm{C_6H_6}$","$\\mathrm{C_3H_3}$"],"answer_index":0,"explanation":"Dividing $\\mathrm{C_6H_6}$ by 6 gives the simplest ratio CH.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-148","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Glucose, $\\mathrm{C_6H_{12}O_6}$, reduces to the empirical set","options":["$\\mathrm{CHO}$","$\\mathrm{CH_2O}$","$\\mathrm{C_2H_4O_2}$","$\\mathrm{C_6H_{12}O_6}$"],"answer_index":1,"explanation":"Each subscript is divisible by 6, leaving CH$_2$O.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-149","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen peroxide $\\mathrm{H_2O_2}$ has the empirical formula","options":["$\\mathrm{HO}$","$\\mathrm{H_2O}$","$\\mathrm{HO_2}$","$\\mathrm{H_2O_2}$"],"answer_index":0,"explanation":"The simplest H : O ratio in hydrogen peroxide is 1 : 1, written HO.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-150","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An organic gas has empirical formula $\\mathrm{CH_2}$ and a molar mass of 56 g mol$^{-1}$. Its molecular formula is","options":["$\\mathrm{C_2H_4}$","$\\mathrm{C_3H_6}$","$\\mathrm{C_4H_8}$","$\\mathrm{C_5H_{10}}$"],"answer_index":2,"explanation":"Empirical mass is 14; $n = 56/14 = 4$, so the molecule is $\\mathrm{C_4H_8}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
